<?php
declare(strict_types=1);
namespace App;
use PHPMailer\PHPMailer\PHPMailer;
final class AccountMail {
 public static function configured():bool {
  if(Support::env('MAIL_TRANSPORT','smtp')==='resend')return Support::env('RESEND_API_KEY')!==''&&filter_var(Support::env('MAIL_FROM_ADDRESS'),FILTER_VALIDATE_EMAIL);
  if(Support::env('MAIL_TRANSPORT','smtp')!=='smtp')return false;
  return Support::env('SMTP_HOST')!==''&&Support::env('SMTP_USERNAME')!==''&&Support::env('SMTP_PASSWORD')!==''&&filter_var(Support::env('MAIL_FROM_ADDRESS'),FILTER_VALIDATE_EMAIL)&&in_array(Support::env('SMTP_ENCRYPTION','tls'),['tls','smtps'],true)&&in_array((int)Support::env('SMTP_PORT','587'),[465,587,2525],true);
 }
 public static function ready():void {if(!self::configured())throw new HttpError(503,'El envío de correos de cuenta todavía no está configurado. Contacta al administrador.');}
 public static function template(string $purpose,string $url):array {
  $verify=$purpose==='verify';$title=$verify?'Confirma tu correo':'Restablece tu contraseña';$action=$verify?'Verificar correo y crear contraseña':'Crear nueva contraseña';$expires=$verify?'24 horas':'30 minutos';$e=fn($s)=>Support::escape($s);
  $text=$verify?'Estás a un paso de crear tu espacio en Zenzales. Confirma tu correo y elige tu contraseña para comenzar.':'Recibimos una solicitud para cambiar la contraseña de tu cuenta de Zenzales.';
  $html='<!doctype html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.$title.'</title></head><body style="margin:0;background:#f4faf7;color:#06444a;font-family:Arial,sans-serif"><div style="display:none;max-height:0;overflow:hidden">'.$title.' en Zenzales. Tu enlace vence en '.$expires.'.</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:32px 16px"><table role="presentation" width="560" cellpadding="0" cellspacing="0" style="width:100%;max-width:560px;background:#ffffff;border:1px solid #d9e7e0;border-radius:20px;overflow:hidden"><tr><td align="center" style="background:#06444a;padding:28px"><img src="cid:zenzales-logo" width="116" height="116" alt="Zenzales" style="display:block;border:0"><p style="color:#c5e9d9;font-size:12px;letter-spacing:2px;margin:16px 0 0">TU CATÁLOGO. TU MARCA.</p></td></tr><tr><td style="padding:32px 28px"><h1 style="font-size:26px;line-height:1.3;margin:0 0 20px">'.$title.'</h1><p style="font-size:16px;line-height:1.7;margin:0 0 24px">'.$text.'</p><table role="presentation" cellpadding="0" cellspacing="0"><tr><td bgcolor="#2db276" style="border-radius:10px"><a href="'.$e($url).'" style="display:inline-block;padding:16px 22px;color:#ffffff;font-size:15px;font-weight:bold;text-decoration:none">'.$action.'</a></td></tr></table><p style="font-size:14px;line-height:1.7;margin:24px 0 16px">Este enlace es de un solo uso y vence en <strong>'.$expires.'</strong>. Si no solicitaste este correo, puedes ignorarlo; tu cuenta no cambiará.</p><p style="font-size:13px;line-height:1.6;color:#526b66;margin:0 0 8px">Si el botón no funciona, copia este enlace:</p><p style="font-size:12px;line-height:1.7;word-break:break-all;margin:0"><a href="'.$e($url).'" style="color:#06444a">'.$e($url).'</a></p></td></tr><tr><td style="background:#edf7f1;padding:20px 28px;color:#526b66;font-size:12px;line-height:1.7">Zenzales · Seguridad de tu cuenta<br>Este es un correo automático. No respondas a esta dirección.</td></tr></table></td></tr></table></body></html>';
  return ['subject'=>$title.' · Zenzales','html'=>$html,'text'=>$title."\n\n".$text."\n\n".$url."\n\nEnlace de un solo uso, válido por ".$expires.'. Si no lo solicitaste, ignora este correo.'];
 }
 public static function send(string $email,string $purpose,string $url,string $id=''):void {
  if(Support::env('MAIL_TRANSPORT','smtp')==='resend'){
   self::ready();$content=self::template($purpose,$url);$html=str_replace('cid:zenzales-logo',Support::escape(rtrim(Support::env('APP_URL'),'/').'/brand/logo-white.png'),$content['html']);$curl=curl_init('https://api.resend.com/emails');$data=['from'=>'Zenzales <'.Support::env('MAIL_FROM_ADDRESS').'>','to'=>[$email],'subject'=>$content['subject'],'html'=>$html,'text'=>$content['text']];
   curl_setopt_array($curl,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>Support::json($data),CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.Support::env('RESEND_API_KEY'),'Idempotency-Key: account-mail-'.$id],CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>20,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2]);
   if(Support::env('HTTP_CA_BUNDLE'))curl_setopt($curl,CURLOPT_CAINFO,Support::env('HTTP_CA_BUNDLE'));
   $result=curl_exec($curl);$status=(int)curl_getinfo($curl,CURLINFO_HTTP_CODE);curl_close($curl);if($result===false||$status<200||$status>=300||!is_string(json_decode($result,true)['id']??null))throw new \RuntimeException('El proveedor no aceptó el correo.');return;
  }
  self::ready();$m=new PHPMailer(true);$m->isSMTP();$m->Host=Support::env('SMTP_HOST');$m->Port=(int)Support::env('SMTP_PORT','587');$m->SMTPAuth=true;$m->Username=Support::env('SMTP_USERNAME');$m->Password=Support::env('SMTP_PASSWORD');$m->SMTPSecure=Support::env('SMTP_ENCRYPTION','tls')==='smtps'?PHPMailer::ENCRYPTION_SMTPS:PHPMailer::ENCRYPTION_STARTTLS;$m->Timeout=15;$m->getSMTPInstance()->Timelimit=20;$m->SMTPDebug=0;$m->CharSet='UTF-8';$m->setFrom(Support::env('MAIL_FROM_ADDRESS'),'Zenzales');$m->addAddress($email);$m->addEmbeddedImage(dirname(__DIR__).'/public/brand/logo-white.png','zenzales-logo','zenzales.png');$content=self::template($purpose,$url);$m->isHTML(true);$m->Subject=$content['subject'];$m->Body=$content['html'];$m->AltBody=$content['text'];$m->send();
 }
 public static function work(int $max=20):array {
  self::ready();$sent=0;$failed=0;$db=Database::connection();
  for($i=0;$i<$max;$i++){
   $db->beginTransaction();try{$r=Database::one("SELECT m.*,t.user_id,t.purpose,t.expires_at,t.used_at,u.email FROM account_mail m JOIN account_tokens t ON t.id=m.token_id JOIN users u ON u.id=t.user_id WHERE (m.status='pending' AND m.next_attempt_at<=now()) OR (m.status='processing' AND m.locked_at<now()-interval '3 minutes') ORDER BY m.created_at FOR UPDATE OF m SKIP LOCKED LIMIT 1");if(!$r){$db->commit();break;}if($r['used_at']||strtotime($r['expires_at'])<=time()) {Database::query("UPDATE account_mail SET status='cancelled',payload_ciphertext=null,updated_at=now() WHERE id=?",[$r['id']]);$db->commit();continue;}Database::query("UPDATE account_mail SET status='processing',locked_at=now(),updated_at=now() WHERE id=?",[$r['id']]);$db->commit();}catch(\Throwable $e){$db->rollBack();throw $e;}
   $attempt=(int)$r['attempts']+1;try{$payload=json_decode(Crypto::decrypt($r['payload_ciphertext'],'account-mail:'.$r['id']),true,32,JSON_THROW_ON_ERROR);self::send($r['email'],$r['purpose'],$payload['url'],$r['id']);Database::query("UPDATE account_mail SET status='sent',payload_ciphertext=null,attempts=?,locked_at=null,last_error=null,updated_at=now() WHERE id=?",[$attempt,$r['id']]);$sent++;}catch(\Throwable){$clearPayload=Database::driver()==='mysql'?($attempt>=5?1:0):($attempt>=5?'true':'false');Database::query("UPDATE account_mail SET status=?,attempts=?,locked_at=null,next_attempt_at=now()+(? * interval '1 second'),last_error='No fue posible enviar el correo con el proveedor configurado.',updated_at=now(),payload_ciphertext=CASE WHEN ? THEN null ELSE payload_ciphertext END WHERE id=?",[$attempt>=5?'failed':'pending',$attempt,min(900,60*2**($attempt-1)),$clearPayload,$r['id']]);$failed++;}
  }return ['sent'=>$sent,'failed'=>$failed];
 }
}
